/**
 * Arancel de Aduanas de la República Dominicana (7ma enmienda): gravamen and ITBIS status of
 * every 8-digit subpartida. `arancel.json` is generated by `scripts/extraer-arancel.mjs` from
 * the PDF in the repo; do not hand-edit it.
 *
 * The ITBIS column of the arancel only marks exemptions, so a line is either exempt or pays
 * the standard rate.
 */
export interface LineaArancel {
  codigo: string;
  gravamen: number;
  itbisExento: boolean;
  descripcion: string;
}

export type Arancel = ReadonlyMap<string, LineaArancel>;

export interface ArancelJson {
  fuente: string;
  /** [codigo, gravamen %, itbis exento (1/0), descripcion] */
  lineas: (string | number)[][];
}

export const ITBIS_GENERAL = 18;

export function parseArancel(json: ArancelJson): Arancel {
  return new Map(json.lineas.map(([codigo, gravamen, exento, descripcion]) => [
    String(codigo),
    { codigo: String(codigo), gravamen: Number(gravamen), itbisExento: exento === 1, descripcion: String(descripcion) },
  ]));
}

let cargando: Promise<Arancel> | null = null;

/**
 * The table is ~460 KB, so it ships as its own chunk, fetched the first time a screen needs
 * it and shared after that. A failed fetch is not cached, so the next call retries.
 */
export function cargarArancel(): Promise<Arancel> {
  cargando ??= import('./arancel.json')
    .then((m) => parseArancel(m.default as ArancelJson))
    .catch((err: unknown) => {
      cargando = null;
      throw err;
    });
  return cargando;
}
